-- HR module (hr.db)
-- Staff records, departments, positions, attendance, leave and training.
-- Generated by Migrations/build_module_databases.py --refresh-schema;
-- foreign keys into another module's file are dropped on purpose.

CREATE TABLE departments (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL UNIQUE COLLATE NOCASE,
                description TEXT DEFAULT '',
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            , is_active INTEGER NOT NULL DEFAULT 1, leadership_position TEXT NOT NULL DEFAULT 'Director',
                parent_id INTEGER, head_employee_id INTEGER,
                unit_type TEXT NOT NULL DEFAULT 'Department');

CREATE TABLE organizational_positions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL COLLATE NOCASE,
                department_id INTEGER,
                level INTEGER NOT NULL DEFAULT 4,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                reports_to_position_id INTEGER,
                is_active INTEGER NOT NULL DEFAULT 1,
                UNIQUE(title, department_id),
                FOREIGN KEY(department_id)
                    REFERENCES departments(id)
                    ON DELETE SET NULL
            );

CREATE TABLE employees (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            employee_code TEXT NOT NULL UNIQUE,
            full_name TEXT NOT NULL,
            email TEXT UNIQUE,
            phone TEXT DEFAULT '',
            department TEXT NOT NULL,
            job_title TEXT NOT NULL,
            hire_date TEXT,
            employment_status TEXT NOT NULL DEFAULT 'Active'
                CHECK (
                    employment_status IN (
                        'Active',
                        'On Leave',
                        'Inactive'
                    )
                ),
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        , gender TEXT DEFAULT '', salary REAL NOT NULL DEFAULT 0, manager_id INTEGER, position_id INTEGER, profile_photo TEXT DEFAULT '', user_id INTEGER, date_of_birth TEXT, address TEXT DEFAULT '', emergency_contact_name TEXT DEFAULT '', emergency_contact_phone TEXT DEFAULT '', employment_type TEXT DEFAULT 'Permanent', work_location TEXT DEFAULT '', education_level TEXT DEFAULT '', field_of_study TEXT DEFAULT '', institution TEXT DEFAULT '', graduation_year INTEGER, certifications TEXT DEFAULT '', work_experience TEXT DEFAULT '', required_documents TEXT DEFAULT '[]', education_documents TEXT DEFAULT '[]', supporting_documents TEXT DEFAULT '[]', notes TEXT DEFAULT '', updated_by INTEGER, updated_by_name TEXT, updated_at TEXT);

CREATE TABLE attendance (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                employee_id INTEGER NOT NULL,
                attendance_date TEXT NOT NULL,
                status TEXT NOT NULL
                    CHECK (
                        status IN ('Present', 'Absent', 'Late', 'Half Day')
                    ),
                check_in TEXT,
                check_out TEXT,
                notes TEXT DEFAULT '',
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (employee_id) REFERENCES employees(id),
                UNIQUE (employee_id, attendance_date)
            );

CREATE TABLE leave_requests (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            employee_id INTEGER NOT NULL,
            leave_type TEXT NOT NULL,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            days_requested INTEGER NOT NULL,
            reason TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'Pending'
                CHECK (status IN ('Pending', 'Approved', 'Rejected')),
            reviewed_by TEXT DEFAULT '',
            review_comment TEXT DEFAULT '',
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (employee_id) REFERENCES employees(id)
        );

CREATE TABLE employee_training (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            employee_id INTEGER NOT NULL,
            course_title TEXT NOT NULL,
            provider TEXT DEFAULT '',
            start_date TEXT NOT NULL,
            end_date TEXT,
            status TEXT NOT NULL DEFAULT 'Planned'
                CHECK (status IN (
                    'Planned', 'In Progress', 'Completed', 'Cancelled'
                )),
            certificate TEXT DEFAULT '',
            notes TEXT DEFAULT '',
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (employee_id) REFERENCES employees(id)
        );

CREATE TABLE hr_settings (
                setting_key TEXT PRIMARY KEY,
                setting_value TEXT NOT NULL
            );

CREATE INDEX idx_employee_department
            ON employees(department);
CREATE INDEX idx_employee_manager
            ON employees(manager_id);
CREATE INDEX idx_employees_position
                ON employees(position_id);
CREATE INDEX idx_employees_status
                ON employees(employment_status);
CREATE INDEX idx_employees_user
                ON employees(user_id);
CREATE INDEX idx_attendance_date
                ON attendance(attendance_date);
CREATE INDEX idx_attendance_employee
                ON attendance(employee_id, attendance_date);
CREATE INDEX idx_leave_employee
                ON leave_requests(employee_id, start_date);
CREATE INDEX idx_leave_status
                ON leave_requests(status);
CREATE INDEX idx_training_employee
                ON employee_training(employee_id, start_date);
CREATE INDEX idx_department_parent
                ON departments(parent_id);
CREATE INDEX idx_positions_reports_to
                ON organizational_positions(reports_to_position_id);
